// The compatibility matrix of every src/app/ entry point, generated from strategies.ts (the committed copy is
// config/phenotypes/COMPATIBILITY.md; tests/registry.test.ts fails when it is out of date).
import { architectureOf } from './architectures.ts';
import { appliedParametersOf } from './injection.ts';
import { compatibleStrategies, incompatibleEntryPoints } from './strategies.ts';

export const matrixMarkdown = () => {
  const lines = [
    '# Phenotype compatibility of the `src/app/` entry points',
    '',
    'Generated by `npm run app -- phenotypes matrix config/phenotypes/COMPATIBILITY.md` from',
    '`src/phenotype/strategies.ts`; do not edit by hand.',
    '',
    '"Applied" parameters are injected into the declaration of the same name in the unmodified strategy file and',
    'every run proves the strategy read them. "Ignored" parameters are ones the file has no mechanism for; a run',
    'prints them as IGNORED. "Strategy constants" are the file\'s own mechanism constants, which no phenotype of',
    "the architecture sets: they keep the file's values and every run lists them. Every compatible file also takes",
    "the execution profile's investment per entry, margin interest rate, first eligible date (added to its arming",
    'guard) and data file.',
    '',
    '## Compatible strategies',
    '',
    '| Entry point | Architecture | Applied parameters | Ignored parameters | Strategy constants (file values) | Integrated |',
    '|---|---|---|---|---|---|'
  ];

  for (const entry of compatibleStrategies) {
    const architecture = architectureOf(entry.architecture);
    const applied = appliedParametersOf(entry);
    const short = (name: string) => architecture.parameters.find((spec) => spec.name === name)!.short;
    const ignored = Object.entries(entry.ignorable);

    lines.push(
      `| \`${entry.script}\` — ${entry.summary} | ${architecture.name} | ${applied.length}/${architecture.parameters.length}: ${applied.map((name) => `${name} (${short(name)})`).join(', ')} | ${ignored.length === 0 ? 'none' : ignored.map(([name, reason]) => `${name} (${short(name)}): ${reason}`).join('; ')} | ${entry.strategyConstants.length === 0 ? 'none' : entry.strategyConstants.join(', ')} | yes |`
    );
  }

  lines.push(
    '',
    '## Entry points that do not take phenotypes',
    '',
    '| Entry point | Category | Integrated | Reason |',
    '|---|---|---|---|'
  );

  for (const entry of incompatibleEntryPoints) {
    lines.push(`| \`${entry.script}\` | ${entry.category} | no | ${entry.reason} |`);
  }

  return `${lines.join('\n')}\n`;
};
